import { cosmiconfig } from "cosmiconfig";
import { dirname, resolve } from "node:path";

const explorer = cosmiconfig("tidytype", {
  searchPlaces: [".tidytyperc", ".tidytyperc.json", "package.json"],
});

/**
 * Find formatting configuration by searching from a file's directory upward.
 *
 * Cosmiconfig reads `.tidytyperc`, `.tidytyperc.json`, and the `tidytype`
 * property in `package.json`.
 *
 * @param {string} filePath Path to the file being formatted.
 * @returns {Promise<Record<string, unknown>>} The discovered configuration, or an empty object.
 */
export async function loadConfigForFile(filePath) {
  const result = await explorer.search(dirname(resolve(filePath)));

  return result?.config ?? {};
}
